import{_ as t,o as e,c as s,a2 as i}from"./chunks/framework.Dxeykp0S.js";const k=JSON.parse('{"title":"Day 4 · FastAPI：现代 Python Web API 框架","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/04-fastapi.md","filePath":"advanced/04-fastapi.md","lastUpdated":1787141678000}'),d={name:"advanced/04-fastapi.md"};function o(l,a,r,n,h,p){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="day-4-·-fastapi-现代-python-web-api-框架" tabindex="-1">Day 4 · FastAPI：现代 Python Web API 框架 <a class="header-anchor" href="#day-4-·-fastapi-现代-python-web-api-框架" aria-label="Permalink to &quot;Day 4 · FastAPI：现代 Python Web API 框架&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>FastAPI 通过装饰器路由、类型驱动的依赖注入、自动生成的 OpenAPI 文档与原生异步支持，提供了一套现代 Web API 开发方式。今天用 FastAPI 从零实现一个 REST API。</p><h2 id="课程目标" tabindex="-1">课程目标 <a class="header-anchor" href="#课程目标" aria-label="Permalink to &quot;课程目标&quot;">​</a></h2><ul><li>掌握路由、请求体、查询参数、路径参数的声明方式</li><li>掌握依赖注入系统（Depends）——FastAPI 的灵魂</li><li>掌握中间件、异常处理、后台任务</li><li>理解自动 OpenAPI 文档的生成原理</li></ul><h2 id="阅读学习" tabindex="-1">阅读学习 <a class="header-anchor" href="#阅读学习" aria-label="Permalink to &quot;阅读学习&quot;">​</a></h2><ul><li><a href="https://fastapi.tiangolo.com/zh/tutorial/" target="_blank" rel="noreferrer">FastAPI 官方教程</a>（文档质量极高，通读 Tutorial - User Guide）</li><li>对照速览：</li></ul><table tabindex="0"><thead><tr><th>Express/NestJS</th><th>FastAPI</th></tr></thead><tbody><tr><td><code>app.get(&#39;/users/:id&#39;)</code></td><td><code>@app.get(&quot;/users/{id}&quot;)</code></td></tr><tr><td><code>req.body</code> + 手动校验/zod</td><td>参数标注 <code>body: UserCreate</code>（pydantic 自动校验）</td></tr><tr><td><code>req.query.page</code></td><td><code>page: int = 1</code>（函数参数即查询参数）</td></tr><tr><td>middleware</td><td><code>@app.middleware(&quot;http&quot;)</code> 或中间件类</td></tr><tr><td>NestJS DI</td><td><code>Depends(get_db)</code></td></tr><tr><td>swagger 手动注解</td><td><strong>自动生成</strong> <code>/docs</code>（Swagger UI）和 <code>/redoc</code></td></tr><tr><td>res.status(201).json()</td><td>直接 return dict，状态码用装饰器参数</td></tr></tbody></table><h2 id="任务作业" tabindex="-1">任务作业 <a class="header-anchor" href="#任务作业" aria-label="Permalink to &quot;任务作业&quot;">​</a></h2><ol><li><p><strong>迷你任务管理 API</strong>：实现一个 Task 管理 REST API：</p><ul><li><code>POST /tasks</code>（创建，pydantic 校验：title 必填 1-100 字符，priority 枚举 low/medium/high）</li><li><code>GET /tasks</code>（支持 <code>?status=&amp;priority=&amp;page=</code> 过滤与分页）</li><li><code>GET /tasks/{id}</code>、<code>PATCH /tasks/{id}</code>、<code>DELETE /tasks/{id}</code></li><li>统一的 404/422 错误响应格式（自定义 exception handler）</li><li>数据先用内存 dict 存储</li></ul></li><li><p><strong>依赖注入体验</strong>：把&quot;获取当前用户&quot;实现为依赖：</p></li></ol><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> get_current_user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(token: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Header(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) -&gt; User: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">@app.get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/me&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> me</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(user: User </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Depends(get_current_user)): </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span></code></pre></div><p>观察 Depends 如何解析、执行并注入依赖，再写一个带参数的依赖工厂（如分页参数依赖）。</p><ol start="3"><li><p><strong>异步 vs 同步路由</strong>：写一个 <code>async def</code> 路由调用 <code>httpx</code> 请求外部 API，一个 <code>def</code> 路由调用同步 <code>time.sleep</code>，压测对比并发能力（可用 <code>uv run python -m http.server</code> 配合 <code>ab</code> 或 <code>wrk</code>，或简单用 asyncio 并发请求计时）。</p></li><li><p><strong>中间件</strong>：写一个请求日志中间件（记录方法、路径、耗时），再写一个请求 ID 中间件（生成 UUID 注入响应头 <code>X-Request-ID</code>）。</p></li><li><p><strong>欣赏文档</strong>：启动后访问 <code>http://localhost:8000/docs</code>，在 Swagger UI 里直接调用你的 API，观察路由与数据模型如何自动转换为 OpenAPI 文档。</p></li></ol><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><ul><li>FastAPI 如何用类型标注同时完成&quot;校验 + 文档生成&quot;？背后是哪个库？</li><li><code>def</code> 路由和 <code>async def</code> 路由分别在哪里执行？在 <code>async def</code> 里调用阻塞函数会发生什么？</li><li>Depends 的依赖可以嵌套吗？依赖的缓存策略是怎样的（同一请求内）？</li><li>FastAPI 和 Flask、Django 的定位差异是什么？</li><li>如何把 FastAPI 应用跑在生产环境？（uvicorn / gunicorn + uvicorn workers）</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>记录今天的学习笔记。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to &quot;拓展阅读&quot;">​</a></h2><ul><li><a href="https://fastapi.tiangolo.com/zh/deployment/" target="_blank" rel="noreferrer">FastAPI 官方：部署指南</a></li></ul><h2 id="预告" tabindex="-1">预告 <a class="header-anchor" href="#预告" aria-label="Permalink to &quot;预告&quot;">​</a></h2><p>下一节学习 <a href="./05-testing">pytest</a>——给你今天写的 API 补上测试。</p>`,21)])])}const u=t(d,[["render",o]]);export{k as __pageData,u as default};
